// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address initialOwner;

    function setUp() public {
        c = new RoundFactory();
        initialOwner = address(this);
        c.initialize();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != initialOwner);
        vm.assume(newOwner != address(0));

        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // even if it succeeded, ownership must still belong to the original owner
        } catch {
            // reverting is the correct behavior for a non-owner caller
        }

        assertTrue(c.owner() == initialOwner, "non-owner must not change ownership");
    }
}
